// OpenWrt (SSH) – papéis no teste de enlace (ADR 015).
//
// Serve iperf3 (`iperf3 -s` em segundo plano, encerrado pelo PID) e dirige
// iperf3 ou btest — este pelo `mikrotik_btest`, o cliente do pacote oficial
// `mikrotik-btest`, que só fala com servidor sem autenticação e recusa
// `-t` ≥ 30. Os pacotes que faltam são instalados pelo Gerenciador de pacotes
// (`openwrt-packages`), que já sabe opkg × apk.

fn pid_dir() {
    "/var/run"
}

// ---------------------------------------------------------------- utilitários

fn or_default(value, fallback) {
    if value == () { fallback } else { value }
}

// Ação de papel chamada sem os parâmetros do teste (pela aba, à mão): recusa
// antes de mexer em qualquer coisa.
fn require_link_test(params, key) {
    if params[key] == () {
        throw "Esta ação faz parte do teste de enlace e recebe os parâmetros dele: rode o teste pela topologia.";
    }
}

// Mensagem de um erro pego por `catch` (texto do `throw` ou erro do sistema).
fn error_text(err) {
    if type_of(err) == "map" && err.message != () { err.message } else { err.to_string() }
}

fn has_binary(device, name) {
    trimmed(device.ssh("command -v " + name + " >/dev/null 2>&1 && echo yes || echo no").stdout) == "yes"
}

// Teto de banda em kbit/s (inteiro), ou `()` sem limite.
fn limit_kbps(limit) {
    if limit == () { return (); }
    let mbps = if type_of(limit) == "f64" { limit } else { limit.to_float() };
    let kbps = (mbps * 1000.0).round().to_int();
    if kbps > 0 { kbps } else { () }
}

fn parse_handle(text) {
    let handle = ();
    try {
        handle = json_parse(text);
    } catch (err) {
        handle = ();
    }
    if type_of(handle) != "map" {
        throw "O `handle` do teste de enlace não é o que o tp_serve devolveu.";
    }
    handle
}

fn empty_report(engine) {
    #{ engine: engine, txBps: (), rxBps: (), txBytes: 0, rxBytes: 0, retransmits: (), samples: [] }
}

// -------------------------------------------------------------------- iperf3

fn iperf3_pidfile(port) {
    pid_dir() + "/nm-iperf3-" + port + ".pid"
}

fn is_iperf3(device, pid) {
    device.ssh("cat /proc/" + pid + "/cmdline 2>/dev/null | tr '\\000' ' '").stdout.contains("iperf3")
}

// `iperf3 -s` em segundo plano, com o PID num arquivo para o `tp_stop`.
fn iperf3_serve(device, params) {
    let port = or_default(params.port, 5201);
    let pidfile = iperf3_pidfile(port);
    let r = device.ssh("iperf3 -s -D -p " + port + " -I " + pidfile + " >/dev/null 2>&1; sleep 1; cat " + pidfile + " 2>/dev/null");
    let pid = regex_capture(r.stdout, "([0-9]+)");
    if pid == () || !is_iperf3(device, pid) {
        throw "O iperf3 não ficou de pé na porta " + port + " (porta ocupada?). " + trimmed(r.stdout + " " + r.stderr);
    }
    #{ port: port, handle: json_encode(#{ engine: "iperf3", pid: parse_int(pid), port: port }) }
}

// Encerra o servidor pelo PID do `handle` — só se ainda for um iperf3.
fn iperf3_stop(device, handle) {
    let pid = handle.pid;
    let port = handle.port;
    if type_of(pid) != "i64" || pid < 2 || type_of(port) != "i64" || port < 1 || port > 65535 {
        throw "O `handle` não traz o PID e a porta do iperf3 que o tp_serve subiu.";
    }
    if is_iperf3(device, pid) {
        device.run("kill " + pid);
    }
    device.run("rm -f " + iperf3_pidfile(port));
    #{ stopped: true }
}

// "56.0" + "M" (de MBytes) → bytes; o iperf3 conta bytes em potências de 1024.
fn iperf3_bytes(value, prefix) {
    let factor = if prefix == "K" { 1024.0 } else if prefix == "M" { 1048576.0 } else if prefix == "G" { 1073741824.0 } else if prefix == "T" { 1099511627776.0 } else { 1.0 };
    (parse_float(value) * factor).round().to_int()
}

// "94.0" + "M" (de Mbits/sec) → bits por segundo (potências de 1000).
fn iperf3_bps(value, prefix) {
    let factor = if prefix == "K" { 1000.0 } else if prefix == "M" { 1000000.0 } else if prefix == "G" { 1000000000.0 } else if prefix == "T" { 1000000000000.0 } else { 1.0 };
    parse_float(value) * factor
}

// O resumo final (`sender`/`receiver`). Vale o `receiver` (o que chegou);
// as retransmissões vêm do `sender`.
fn iperf3_summary(stdout, stderr, streams) {
    let text = stdout + "\n" + stderr;
    let failure = regex_capture(text, "iperf3: error - ([^\\n]+)");
    if failure != () {
        throw "O iperf3 falhou: " + trimmed(failure);
    }
    let id = if streams > 1 { "SUM" } else { "\\s*[0-9]+" };
    let pattern = "^\\[" + id + "\\]\\s+[0-9.]+-[0-9.]+\\s+sec\\s+([0-9.]+)\\s+([KMGT]?)Bytes\\s+([0-9.]+)\\s+([KMGT]?)bits/sec(?:\\s+([0-9]+))?\\s+(sender|receiver)$";
    let sender = ();
    let receiver = ();
    for line in lines(text) {
        let g = regex_groups(line, pattern);
        if g == () { continue; }
        let entry = #{
            bytes: iperf3_bytes(g[0], g[1]),
            bps: iperf3_bps(g[2], g[3]),
            retransmits: if g[4] == () { () } else { parse_int(g[4]) }
        };
        if g[5] == "sender" { sender = entry; } else { receiver = entry; }
    }
    if sender == () && receiver == () {
        throw "O iperf3 terminou sem o resumo final: " + trimmed(text);
    }
    let best = if receiver != () { receiver } else { sender };
    #{ bps: best.bps, bytes: best.bytes, retransmits: if sender == () { () } else { sender.retransmits } }
}

// Um sentido do teste, com as linhas de 1 s viradas amostras ao vivo (o
// resumo final, que termina em sender/receiver, fica de fora).
fn iperf3_leg(device, command, duration, streams, flow) {
    let id = if streams > 1 { "\\[SUM\\]" } else { "\\[\\s*[0-9]+\\]" };
    let r = device.ssh_live(command, #{
        timeout_ms: duration * 1000 + 20000,
        progress: #{
            pattern: "^" + id + "\\s+[0-9.]+-[0-9.]+\\s+sec\\s+[0-9.]+\\s+[KMGT]?Bytes\\s+(?<value>[0-9.]+)\\s*(?<unit>[KMGT]?bits/sec)(?:\\s+[0-9]+(?:\\s+[0-9.]+\\s+[KMGT]?Bytes)?)?\\s*$",
            flow: flow
        }
    });
    iperf3_summary(r.stdout, r.stderr, streams)
}

fn add_retransmits(total, more) {
    if more == () { total } else if total == () { more } else { total + more }
}

// `send` mede este equipamento enviando; `receive`, recebendo (`-R`); `both`,
// os dois em sequência.
fn iperf3_run(device, params) {
    let port = or_default(params.port, 5201);
    let duration = or_default(params.durationS, 5);
    let streams = or_default(params.streams, 1);
    let direction = or_default(params.direction, "both");
    let command = "iperf3 -c " + shell_quote(params.target) + " -p " + port + " -t " + duration + " -P " + streams;
    let limit = limit_kbps(params.limitMbps);
    if limit != () {
        let per_stream = limit / streams;
        if per_stream < 1 { per_stream = 1; }
        command += " -b " + per_stream + "K";
    }
    command += " --forceflush -i 1 -f m";
    let report = empty_report("iperf3");
    if direction != "receive" {
        let leg = iperf3_leg(device, command, duration, streams, "tx");
        report.txBps = leg.bps;
        report.txBytes = leg.bytes;
        report.retransmits = add_retransmits(report.retransmits, leg.retransmits);
    }
    if direction != "send" {
        let leg = iperf3_leg(device, command + " -R", duration, streams, "rx");
        report.rxBps = leg.bps;
        report.rxBytes = leg.bytes;
        report.retransmits = add_retransmits(report.retransmits, leg.retransmits);
    }
    report
}

// --------------------------------------------------------------------- btest

// Teto do `mikrotik_btest` por sentido: ele recusa `-t` de 30 em diante.
fn btest_max_duration() {
    29
}

// "Rx:   94.50 Mb/s\tTx:   93.20 Mb/s" — o `mikrotik_btest` divide por
// 1048576 (Mibit/s), apesar do rótulo; a última linha é o resumo.
fn btest_run(device, params) {
    let duration = or_default(params.durationS, 5);
    if duration > btest_max_duration() { duration = btest_max_duration(); }
    let port = or_default(params.port, 2000);
    let direction = or_default(params.direction, "both");
    let command = "mikrotik_btest -t " + duration + " -d " + direction + " " + shell_quote(params.target + ":" + port);
    let r = device.ssh_live(command, #{
        timeout_ms: duration * 1000 + 20000,
        progress: #{ pattern: "(?<flow>Rx|Tx):\\s*(?<value>[0-9.]+)\\s*(?<unit>Mb/s)" }
    });
    let text = r.stdout + "\n" + r.stderr;
    if text.contains("Auth failed") {
        throw "O servidor btest pediu autenticação, e o cliente do OpenWrt só fala com servidor sem autenticação (Auth failed).";
    }
    if text.contains("failed to connect") || text.contains("Invalid host") {
        throw "O mikrotik_btest não conectou em " + params.target + ":" + port + ": " + trimmed(text);
    }
    let t = text;
    t.replace("\r", "\n");
    let summary = ();
    for line in lines(t) {
        if line.contains("Mb/s") { summary = line; }
    }
    if summary == () {
        throw "O mikrotik_btest terminou sem resultado: " + trimmed(text);
    }
    let rx = regex_capture(summary, "Rx:\\s*([0-9.]+)");
    let tx = regex_capture(summary, "Tx:\\s*([0-9.]+)");
    let report = empty_report("btest");
    if direction != "receive" && tx != () { report.txBps = parse_float(tx) * 1048576.0; }
    if direction != "send" && rx != () { report.rxBps = parse_float(rx) * 1048576.0; }
    report
}

// -------------------------------------------------------------------- ações

fn detect(device, params) {
    let release = parse_kv(device.run("cat /etc/openwrt_release"), "=");
    #{
        firmware: release.DISTRIB_RELEASE,
        target: release.DISTRIB_TARGET,
        iperf3: has_binary(device, "iperf3"),
        btest: has_binary(device, "mikrotik_btest")
    }
}

fn tp_prepare(device, params) {
    require_link_test(params, "engine");
    let role = or_default(params.role, "drive");
    if params.engine == "btest" && role == "serve" {
        return #{ ready: false, installed: [], message: "O OpenWrt não tem servidor btest: aqui o btest só dirige (cliente)." };
    }
    let pkg_name = if params.engine == "btest" { "mikrotik-btest" } else { "iperf3" };
    let binary = if params.engine == "btest" { "mikrotik_btest" } else { "iperf3" };
    if has_binary(device, binary) {
        return #{ ready: true, installed: [], message: "O " + binary + " já está instalado." };
    }
    let failure = ();
    try {
        device.use_plugin("openwrt-packages", "install_package", #{ name: pkg_name });
    } catch (err) {
        failure = error_text(err);
    }
    if failure != () {
        return #{
            ready: false,
            installed: [],
            message: "Não deu para instalar o pacote " + pkg_name + " (o mikrotik-btest só existe nos repositórios a partir do OpenWrt 23.05; o roteador precisa de internet e de espaço na flash). " + failure
        };
    }
    if !has_binary(device, binary) {
        return #{ ready: false, installed: [pkg_name], message: "O pacote " + pkg_name + " foi instalado, mas o " + binary + " não apareceu no PATH." };
    }
    #{ ready: true, installed: [pkg_name], message: "Pacote " + pkg_name + " instalado." }
}

fn tp_serve(device, params) {
    require_link_test(params, "engine");
    if params.engine != "iperf3" {
        throw "O OpenWrt só serve iperf3; o btest aqui só dirige.";
    }
    iperf3_serve(device, params)
}

fn tp_stop(device, params) {
    require_link_test(params, "handle");
    iperf3_stop(device, parse_handle(params.handle))
}

fn tp_run(device, params) {
    require_link_test(params, "target");
    if or_default(params.engine, "iperf3") == "btest" {
        btest_run(device, params)
    } else {
        iperf3_run(device, params)
    }
}
